/*
 * sfun_flux_vector_control: Level-2 C MEX S-function generated by motulator_plecs
 * from the C-Script code of the PLECS model. The C-Script macros are
 * defined with the Simulink API. The state of the code is in static
 * variables, so a model can contain one instance of the block.
 *
 * Build with a C99 compiler with complex.h (gcc, clang, or MinGW-w64):
 *     mex -I<motulator_plecs/c> sfun_flux_vector_control.c
 */

#define S_FUNCTION_NAME sfun_flux_vector_control
#define S_FUNCTION_LEVEL 2

#include "simstruc.h"

#define InputSignal(i, j) (ssGetInputPortRealSignal(S, (i))[j])
#define OutputSignal(i, j) (ssGetOutputPortRealSignal(S, (i))[j])
#define ParamRealData(i, j) (mxGetPr(ssGetSFcnParam(S, (i)))[j])
#define ParamDim(i, d)                                                           \
    ((int)((d) == 0 ? mxGetM(ssGetSFcnParam(S, (i)))                             \
                    : mxGetN(ssGetSFcnParam(S, (i)))))
#define SetErrorMessage(msg) ssSetErrorStatus(S, (msg))
#define ContState(i) (ssGetContStates(S)[i])
#define ContDeriv(i) (ssGetdX(S)[i])

/* Declarations of the C-Script (after simstruc.h, since complex.h
 * defines the macro I) */
/* Generated by motulator_plecs.sm. The control algorithms are in the
 * included C files. The parameters come from the mask of the subsystem. */
#include "common.c"
#include "gradnet.c"
#include "sm_parameters.c"
#include "sm_control_loci.c"
#include "sm_flux_vector.c"

#define P(i, j) ParamRealData(i, j)
#define PDIM(i) (ParamDim(i, 0) * ParamDim(i, 1))

/* Parameter value, or NAN for an empty parameter (None in motulator) */
#define PARAM(i) (PDIM(i) > 0 ? P(i, 0) : NAN)

/* Check that a GradNet in the parameters i0, i0 + 1, ... (GRADNET_FIELDS) fits
 * in the arrays of the C port (in the start function only, returns on error) */
#define CHECK_GRADNET(i0) \
    do { \
        if ((int)P((i0), 0) > GRADNET_MAX_IN_DIM \
            || PDIM((i0) + 3) > GRADNET_MAX_EMBED_DIM) { \
            SetErrorMessage("GradNet too large: in_dim must be at most " \
                            "4 and embed_dim at most " \
                            "64."); \
            return; \
        } \
    } while (0)

/* Read a GradNet from the parameters i0, i0 + 1, ... (GRADNET_FIELDS) */
#define READ_GRADNET(net, i0) \
    do { \
        (net).in_dim = (int)P((i0), 0); \
        (net).mu_dim = (int)P((i0) + 1, 0); \
        (net).embed_dim = PDIM((i0) + 3); \
        for (int j_ = 0; j_ < (net).embed_dim; j_++) { \
            for (int k_ = 0; k_ < (net).in_dim; k_++) { \
                (net).W[j_][k_] = P((i0) + 2, j_ + (net).embed_dim * k_); \
            } \
            (net).b[j_] = P((i0) + 3, j_); \
        } \
        for (int k_ = 0; k_ < (net).in_dim; k_++) { \
            (net).mu_log[k_] = (k_ < (net).mu_dim) ? P((i0) + 4, k_) : 0.0; \
            (net).bias[k_] = P((i0) + 5, k_); \
        } \
        (net).activation = (GradNetActivation)(int)P((i0) + 6, 0); \
        (net).beta_log = P((i0) + 7, 0); \
        (net).p = (int)P((i0) + 8, 0); \
        (net).in_base = P((i0) + 9, 0); \
        (net).out_base = P((i0) + 10, 0); \
    } while (0)

static VectorControlSystem ctrl;

/* Ports and parameters of the C-Script */
static const int INPUT_WIDTHS[] = {1, 3, 1, 1};
static const int FEEDTHROUGH[] = {1, 1, 1, 1};
static const int OUTPUT_WIDTHS[] = {3, 2, 2, 2, 3};
#define NUM_INPUTS 4
#define NUM_OUTPUTS 5
#define NUM_PARAMS 34

static void mdlInitializeSizes(SimStruct *S)
{
    ssSetNumSFcnParams(S, NUM_PARAMS);
    ssSetNumContStates(S, 0);
    ssSetNumDiscStates(S, 0);
    if (!ssSetNumInputPorts(S, NUM_INPUTS)) {
        return;
    }
    for (int k = 0; k < NUM_INPUTS; k++) {
        ssSetInputPortWidth(S, k, INPUT_WIDTHS[k]);
        ssSetInputPortDirectFeedThrough(S, k, FEEDTHROUGH[k]);
        ssSetInputPortRequiredContiguous(S, k, 1);
    }
    if (!ssSetNumOutputPorts(S, NUM_OUTPUTS)) {
        return;
    }
    for (int k = 0; k < NUM_OUTPUTS; k++) {
        ssSetOutputPortWidth(S, k, OUTPUT_WIDTHS[k]);
    }
    ssSetNumSampleTimes(S, 1);
    ssSetOptions(S, SS_OPTION_EXCEPTION_FREE_CODE);
#if defined(MATLAB_MEX_FILE)
    if (ssGetNumSFcnParams(S) != ssGetSFcnParamsCount(S)) {
        return; /* Reported by Simulink */
    }
    for (int k = 0; k < NUM_PARAMS; k++) {
        const mxArray *p = ssGetSFcnParam(S, k);
        if (!mxIsDouble(p) || mxIsComplex(p)) {
            SetErrorMessage(
                "The parameters must be real double arrays.");
            return;
        }
        ssSetSFcnParamTunable(S, k, SS_PRM_NOT_TUNABLE);
    }
    if (ParamDim(18, 0) * ParamDim(18, 1) != 1
        || !(ParamRealData(18, 0) > 0.0)) {
        SetErrorMessage("The sampling period must be a positive scalar.");
        return;
    }
#endif
}

static void mdlInitializeSampleTimes(SimStruct *S)
{
    ssSetSampleTime(S, 0, ParamRealData(18, 0));
    ssSetOffsetTime(S, 0, 0.0);
}

#define MDL_START
static void mdlStart(SimStruct *S)
{
    /* Check the parameters of the mask */
    if (PDIM(0) != 1) {
        SetErrorMessage("n_p must be a scalar.");
        return;
    }
    if (PDIM(1) != 1) {
        SetErrorMessage("R_s must be a scalar.");
        return;
    }
    if (PDIM(6) != 1) {
        SetErrorMessage("i_s_max must be a scalar.");
        return;
    }
    if (PDIM(18) != 1) {
        SetErrorMessage("T_s must be a scalar.");
        return;
    }
    if (PDIM(19) != 1) {
        SetErrorMessage("speed_J must be a scalar.");
        return;
    }
    if (PDIM(20) != 1) {
        SetErrorMessage("speed_alpha_s must be a scalar.");
        return;
    }
    if (PDIM(11) != 0 && PDIM(11) != 2) {
        SetErrorMessage("k_o must be [] or [k0 k1].");
        return;
    }

    /* Machine model parameters: SaturatedSynchronousMachinePars with a GradNet
     * flux map, or SynchronousMachinePars with constant inductances */
    SynchronousMachinePars par;
    if (PDIM(23) > 0) {
        GradNet flux_map;
        CHECK_GRADNET(23);
        READ_GRADNET(flux_map, 23);
        par = saturated_synchronous_machine_pars(
            P(0, 0), P(1, 0), &flux_map);
    } else {
        if (PDIM(3) != 1 || PDIM(4) != 1 || PDIM(5) != 1) {
            SetErrorMessage("L_d, L_q, and psi_f needed without a flux map.");
            return;
        }
        par = synchronous_machine_pars(
            P(0, 0), P(1, 0), P(3, 0), P(4, 0),
            P(5, 0));
    }

    /* Flux-vector controller configuration (FluxVectorControllerCfg), the
     * defaults are used for empty parameters */
    FluxVectorControllerCfg cfg = flux_vector_controller_cfg(P(6, 0));
    if (PDIM(7) > 0) {
        cfg.alpha_tau = P(7, 0);
    }
    if (PDIM(8) > 0) {
        cfg.alpha_psi = P(8, 0);
    }
    if (PDIM(9) > 0) {
        cfg.alpha_i = P(9, 0);
    }
    if (PDIM(10) > 0) {
        cfg.alpha_o = P(10, 0);
    }
    if (PDIM(12) > 0) {
        cfg.psi_s_min = P(12, 0);
    }
    if (PDIM(13) > 0) {
        cfg.psi_s_max = P(13, 0);
    }
    if (PDIM(14) > 0) {
        cfg.k_u = P(14, 0);
    }
    if (PDIM(15) > 0) {
        cfg.k_mtpv = P(15, 0);
    }
    if (PDIM(16) > 0) {
        cfg.J = P(16, 0);
    }
    if (PDIM(17) > 0) {
        cfg.sensorless = P(17, 0);
    }
    if (PDIM(18) > 0) {
        cfg.T_s = P(18, 0);
    }
    if (PDIM(11) == 2) {
        cfg.k_o[0] = P(11, 0);
        cfg.k_o[1] = P(11, 1);
    }

    /* Speed controller (SpeedController) */
    PIController speed_ctrl = speed_controller(
        P(19, 0), P(20, 0), PARAM(21),
        PDIM(22) > 0 ? P(22, 0) : INFINITY);

    vector_control_system_init(&ctrl, par, &cfg, speed_ctrl);
}

static void mdlOutputs(SimStruct *S, int_T tid)
{
    UNUSED_ARG(tid);
    /* Measurements */
    double w_M_ref = InputSignal(0, 0);
    double i_s_abc[3] = {InputSignal(1, 0), InputSignal(1, 1),
                         InputSignal(1, 2)};
    Measurements meas = {abc2complex(i_s_abc), InputSignal(2, 0),
                         InputSignal(3, 0)};

    vector_control_system_compute_output(&ctrl, &meas, w_M_ref);

    /* Duty ratios, delayed by the Delay block outside the subsystem */
    for (int k = 0; k < 3; k++) {
        OutputSignal(0, k) = ctrl.ref.d_abc[k];
    }

    /* Monitored signals */
    OutputSignal(1, 0) = ctrl.ref.w_M;
    OutputSignal(1, 1) = ctrl.fbk.w_M;
    OutputSignal(2, 0) = ctrl.ref.tau_M;
    OutputSignal(2, 1) = ctrl.fbk.tau_M;
    OutputSignal(3, 0) = ctrl.ref.psi_s;
    OutputSignal(3, 1) = cabs(ctrl.fbk.psi_s);
    OutputSignal(4, 0) = ctrl.fbk.theta_m;
    OutputSignal(4, 1) = creal(ctrl.fbk.i_s);
    OutputSignal(4, 2) = cimag(ctrl.fbk.i_s);
}

#define MDL_UPDATE
static void mdlUpdate(SimStruct *S, int_T tid)
{
    UNUSED_ARG(tid);
    vector_control_system_update(&ctrl);
}

static void mdlTerminate(SimStruct *S)
{
    UNUSED_ARG(S);
}

#ifdef MATLAB_MEX_FILE
#include "simulink.c"
#else
#include "cg_sfun.h"
#endif
